/tmp/lean-procshim.c.content:
#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

extern char *program_invocation_name;

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

ssize_t readlink(const char *path, char *buffer, size_t size) {
  static readlink_fn next_readlink;
  if (next_readlink == NULL) {
    next_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
  }

  size_t length = strlen(path);
  if (strncmp(path, "/proc/", 6) == 0 && length >= 10 &&
      strcmp(path + length - 4, "/exe") == 0) {
    char resolved[PATH_MAX];
    if (realpath(program_invocation_name, resolved) != NULL) {
      size_t resolved_length = strlen(resolved);
      if (resolved_length > size) {
        resolved_length = size;
      }
      memcpy(buffer, resolved, resolved_length);
      return (ssize_t)resolved_length;
    }
  }

  return next_readlink(path, buffer, size);
}

